"""NoleCareerShield — one-file setup. Run once: python setup_jobboard.py"""
import base64, os

FILES = {
    'README.md': '',
    'app.py': '',
    'requirements.txt': 'ZmFzdGFwaT49MC4xMTAKdXZpY29ybj49MC4yNwpweXRob24tbXVsdGlwYXJ0Pj0wLjAuOQpkbnNweXRob24+PTIuNgpweWRhbnRpYz49Mi42Cg==',
    'scam_detector/BUILDING_A_CORPUS.md': '',
    'scam_detector/README.md': '',
    'scam_detector/__init__.py': '',
    'scam_detector/api.py': '',
    'scam_detector/data/labeled_seed.jsonl': '',
    'scam_detector/data/real_corpus.jsonl': '',
    'scam_detector/enrichment/__init__.py': '',
    'scam_detector/enrichment/compensation.py': '',
    'scam_detector/enrichment/domain_age.py': '',
    'scam_detector/enrichment/mx_check.py': '',
    'scam_detector/enrichment/url_flow.py': '',
    'scam_detector/requirements.txt': 'ZmFzdGFwaT49MC4xMTAKdXZpY29ybj49MC4yNwpkbnNweXRob24+PTIuNgpweWRhbnRpYz49Mi42Cg==',
    'scam_detector/rules.py': '',
    'scam_detector/scorer.py': '',
    'scam_detector/tools/__init__.py': '',
    'scam_detector/tools/evaluate.py': '',
}

def main():
    for path, b64 in FILES.items():
        d = os.path.dirname(path)
        if d: os.makedirs(d, exist_ok=True)
        open(path, "wb").write(base64.b64decode(b64))
    print(f"Wrote {len(FILES)} files.")
    print()
    print("Next:")
    print("  pip install -r requirements.txt")
    print("  set a password:  export ADMIN_PASSWORD=your-secret   (Windows: set ADMIN_PASSWORD=your-secret)")
    print("  python -m uvicorn app:app --reload")
    print("  public site: http://127.0.0.1:8000    review queue: http://127.0.0.1:8000/admin")

if __name__ == "__main__":
    main()
